import { MongoClient } from "mongodb";

export async function connectMongo(url: string): Promise<MongoClient> {
  const client = new MongoClient(url, {
    maxPoolSize: 20,
    serverSelectionTimeoutMS: 5_000,
  });
  await client.connect();
  await client.db().command({ ping: 1 });
  return client;
}

import { type Db, MongoServerError, type ObjectId } from "mongodb";
import { ConflictError } from "../../domain/errors.ts";

export interface FeedbackDoc {
  _id?: ObjectId;
  bookingId: number;
  roomId: number;
  userId: number | null;
  rating: number;
  comment: string | null;
  tags: string[];
  createdAt: Date;
}

export function createFeedbackRepository(db: Db) {
  const feedback = db.collection<FeedbackDoc>("room_feedback");

  return {
    async create(doc: FeedbackDoc): Promise<ObjectId> {
      try {
        const result = await feedback.insertOne(doc);
        return result.insertedId;
      } catch (err) {
        if (err instanceof MongoServerError && err.code === 11000) {
          throw new ConflictError("feedback-exists", "This booking already has feedback.");
        }
        throw err;
      }
    },

    findByBooking(bookingId: number) {
      return feedback.findOne({ bookingId });
    },

    listForRoom(roomId: number, limit: number) {
      return feedback
        .find({ roomId }, { projection: { _id: 0, userId: 0 } })
        .sort({ createdAt: -1 })
        .limit(limit)
        .toArray();
    },

    async editComment(bookingId: number, comment: string): Promise<boolean> {
      const result = await feedback.updateOne({ bookingId }, { $set: { comment } });
      return result.matchedCount === 1;
    },

    async addTag(bookingId: number, tag: string): Promise<boolean> {
      const result = await feedback.updateOne({ bookingId }, { $push: { tags: tag } });
      return result.matchedCount === 1;
    },

    async remove(bookingId: number): Promise<boolean> {
      const result = await feedback.deleteOne({ bookingId });
      return result.deletedCount === 1;
    },
  };
}

export type FeedbackRepository = ReturnType<typeof createFeedbackRepository>;

import type { Db } from "mongodb";

const NINETY_DAYS = 90 * 24 * 60 * 60;

export async function ensureFeedbackIndexes(db: Db): Promise<void> {
  await db.collection("room_feedback").createIndexes([
    { key: { bookingId: 1 }, name: "bookingId_unique", unique: true },
    { key: { roomId: 1, createdAt: -1 }, name: "room_latest" },
  ]);
  await db.collection("activity").createIndex({ at: 1 }, { expireAfterSeconds: NINETY_DAYS });
}

import type { Collection } from "mongodb";
import type { FeedbackDoc } from "./feedback.repository.ts";

export interface RoomRating {
  roomId: number;
  average: number;
  count: number;
}

export function ratingsForRooms(feedback: Collection<FeedbackDoc>, roomIds: number[]) {
  return feedback
    .aggregate<RoomRating>([
      { $match: { roomId: { $in: roomIds } } },
      { $group: { _id: "$roomId", average: { $avg: "$rating" }, count: { $sum: 1 } } },
      { $sort: { average: -1 } },
      {
        $project: {
          _id: 0,
          roomId: "$_id",
          average: { $round: ["$average", 2] },
          count: 1,
        },
      },
    ])
    .toArray();
}

import { Router } from "express";
import { z } from "zod";
import type { FeedbackRepository } from "./feedback.repository.ts";

const EditFeedback = z.strictObject({
  comment: z.string().trim().max(2000),
});
const BookingId = z.coerce.number().int().positive();

export function feedbackRoutes(feedback: FeedbackRepository) {
  const router = Router();

  router.patch("/bookings/:bookingId/feedback", async (req, res) => {
    // Never: updateOne({ bookingId: req.params.bookingId }, { $set: req.body })
    const bookingId = BookingId.parse(req.params.bookingId);
    const { comment } = EditFeedback.parse(req.body);
    const found = await feedback.editComment(bookingId, comment);
    if (!found) return res.sendStatus(404);
    res.sendStatus(204);
  });

  return router;
}

import type { MongoClient } from "mongodb";
import { NotFoundError } from "../../domain/errors.ts";

export async function hideFeedback(
  client: MongoClient,
  bookingId: number,
  staffId: number,
  reason: string,
) {
  const db = client.db();
  await client.withSession((session) =>
    session.withTransaction(async () => {
      const result = await db
        .collection("room_feedback")
        .updateOne({ bookingId }, { $set: { hidden: true } }, { session });
      if (result.matchedCount === 0)
        throw new NotFoundError(`No feedback for booking ${bookingId}.`);
      await db
        .collection("moderation_log")
        .insertOne({ bookingId, staffId, reason, at: new Date() }, { session });
    }),
  );
}

export interface FeedbackInput {
  rating: number;
  comment: string | null;
  tags: string[];
}

interface Deps {
  bookings: BookingRepository;
  feedback: FeedbackRepository;
  clock: () => Date;
}

export function createFeedbackService({ bookings, feedback, clock }: Deps) {
  return {
    async submit(userId: number, bookingId: number, input: FeedbackInput): Promise<void> {
      const booking = await bookings.findById(bookingId);
      if (!booking || booking.userId !== userId) {
        throw new NotFoundError(`No booking with id ${bookingId}.`);
      }
      const now = clock();
      if (booking.status !== "confirmed" || booking.endsAt > now) {
        throw new ConflictError("feedback-not-open", "Feedback opens when the booking ends.");
      }
      await feedback.create({
        bookingId,
        roomId: booking.roomId,
        userId,
        rating: input.rating,
        comment: input.comment,
        tags: input.tags,
        createdAt: now,
      });
    },
  };
}

export async function watchLowRatings(
  client: MongoClient,
  token: ResumeToken | undefined,
  notify: (doc: FeedbackDoc) => Promise<void>,
  saveToken: (token: ResumeToken) => Promise<void>,
) {
  const stream = client
    .db()
    .collection<FeedbackDoc>("room_feedback")
    .watch<FeedbackDoc, ChangeStreamInsertDocument<FeedbackDoc>>(
      [{ $match: { operationType: "insert", "fullDocument.rating": { $lte: 2 } } }],
      { resumeAfter: token },
    );
  for await (const change of stream) {
    await notify(change.fullDocument);
    await saveToken(change._id);
  }
}
